// server.ts — the dual-schema HTTP server (spec §3/§9): one process
// hosting /world (simulated actions), /twin (the SMART digital twin
// interface — generated or baked; a clear placeholder until then),
// GraphiQL playgrounds for both, and the landing/bench at /.
import { createServer, type Server } from 'node:http'
import { createYoga, createSchema, createGraphQLError, type Plugin } from 'graphql-yoga'
import { GraphQLError, type DocumentNode, type GraphQLSchema } from 'graphql'
import { readFile } from 'node:fs/promises'
import { join, extname } from 'node:path'
import type { TwinContract } from './twin-contract.js'
import { readerFor, instrumentMirrorObject, type TwinIo } from './twin-schema.js'
import { FRESH_WITHIN_HEADER } from './twin-openapi.js'

export interface TwinStreamSource {
  /** The clock that drives indication updates. */
  clock: { onAdvance: (fn: () => void) => () => void; now: () => number }
  /** Read one twin target (indication, state, environmental_context, …). */
  read: (target: string) => unknown
  /** Which targets to stream. */
  targets: string[]
}

export interface SimServerOptions {
  worldSchema: GraphQLSchema
  /** the generated/baked twin schema; absent → honest placeholder. */
  twinSchema?: GraphQLSchema | undefined
  /** static bench directory (the @primmel/sst-bench build output); absent →
   *  the built-in landing page. */
  benchDir?: string | undefined
  /** 0 = ephemeral. */
  port: number
  /** landing-page title block (instrument id + scenario). */
  title?: string | undefined
  /** bearer token guarding /world MUTATIONS (the TODO.v2/11 opt-in):
   *  set ⇒ every world mutation requires `Authorization: Bearer
   *  <token>`; world queries and the whole /twin channel stay open.
   *  Absent ⇒ the world channel is fully open (the localhost dev
   *  posture). The bins wire this from SIM_WORLD_TOKEN. */
  worldToken?: string | undefined
  /** CORS origins for browser clients (TODO.ops/29 — the hosted
   *  platform's pages driving a LOCAL sim): comma-separated origins,
   *  or '*' (the demo posture — a simulator serves no secrets).
   *  An entry WITHOUT a port ('http://localhost') matches any port on
   *  that host. The bins wire this from SST_CORS_ORIGINS and default to
   *  the localhost pair when unset — a local sim is a development and
   *  training tool, so browser pages on any local port may drive it;
   *  set the env explicitly to lock origins down. */
  corsOrigins?: string | undefined
  /** When present, adds a GET /twin/stream endpoint serving real-time
   *  Server-Sent Events for continuous twin indication monitoring.
   *  Clients connect with `EventSource('/twin/stream?targets=indication,state')`.
   *  Each event: `{ target, value, servedAt, freshness }`. */
  twinStream?: TwinStreamSource | undefined
  /** The OpenAPI twin leg (spec §12 §5.5): the generated OpenAPI 3.1
   *  document, served at GET /openapi.json. */
  openApiDoc?: Record<string, unknown> | undefined
  /** The REST projection of the twin contract (the OpenAPI leg's
   *  runtime half): GET /twin/registers/<target>, POST
   *  /twin/operations/<op_id>, GET /twin/instrument — the same readers
   *  the generated GraphQL resolvers bind to. The single-instrument
   *  boot binds the TwinIo (`readerFor` resolves each serve); the
   *  composite boot binds a `read` delegate (its registers resolve via
   *  the decomposition map to the components' readers — the same
   *  functions the composite schema's resolvers call). */
  twinRest?: TwinRestBinding | undefined
}

/** The REST projection's reader binding: the single-instrument shape
 *  (contract + TwinIo) or the composite shape (contract + a per-target
 *  read delegate). Command operations run only against a TwinIo — the
 *  composite twin exposes no mutation leg, so a declared command under
 *  a read-delegate binding answers 501. */
export type TwinRestBinding =
  | { contract: TwinContract; io: TwinIo }
  | { contract: TwinContract; read: (target: string) => unknown | Promise<unknown> }

export interface SimServer {
  url: string
  close: () => Promise<void>
}

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css',
  '.json': 'application/json', '.svg': 'image/svg+xml', '.png': 'image/png', '.ico': 'image/x-icon',
}

const TWIN_PLACEHOLDER_MESSAGE = 'twin schema not generated/baked — pass twinSchema to createSimServer (see docs §6/§9)'

/** The CORS origin matcher: an exact entry matches the request origin; an
 *  entry WITHOUT a port ('http://localhost') matches any port on that
 *  host — the local-dev default lists the localhost pair this way so any
 *  dev-server port can drive a local sim. (Shared with the worker
 *  adapter — the same matcher must answer both transports.) */
export function corsOriginAllowed(configured: string, requestOrigin: string): boolean {
  let parsed: URL | null = null
  try {
    parsed = new URL(requestOrigin)
  } catch {
    return false
  }
  for (const raw of configured.split(',')) {
    const entry = raw.trim()
    if (!entry) continue
    if (entry === requestOrigin) return true
    // Port-less entry: scheme + host match, any port.
    if (!/:\d+$/.test(entry)) {
      try {
        const e = new URL(entry)
        if (e.protocol === parsed.protocol && e.hostname === parsed.hostname) return true
      } catch { /* a malformed entry never matches */ }
    }
  }
  return false
}

/** The operation type the request will execute, honoring operationName
 *  the way graphql-js selects it (absent → the single operation).
 *  (Shared with the worker adapter.) */
export function operationTypeOf(document: DocumentNode, operationName: string | null | undefined): string | undefined {
  for (const def of document.definitions) {
    if (def.kind !== 'OperationDefinition') continue
    if (operationName == null || def.name?.value === operationName) return def.operation
  }
  return undefined
}

/** The Authorization header off a request view (the node request in the
 *  node server, a plain header view in the worker adapter). */
export function authorizationOf(req: unknown): string | undefined {
  const header = (req as { headers?: { authorization?: string | string[] } } | null)?.headers?.authorization
  return Array.isArray(header) ? header[0] : header
}

/** The /world mutation guard (TODO.v2/11): an envelop plugin at the
 *  transport edge — never in the physics. A mutation without the
 *  bearer token is rejected 401 before any resolver runs; queries
 *  (and named-operation documents selecting a query) pass through.
 *  (Shared with the worker adapter — the same guard rides both
 *  transports.) */
export function worldMutationGuard(token: string): Plugin<{ req: Request }> {
  return {
    onExecute({ args }) {
      if (operationTypeOf(args.document, args.operationName) !== 'mutation') return
      if (authorizationOf(args.contextValue.req) !== `Bearer ${token}`) {
        throw createGraphQLError(
          'unauthorized: /world mutations require Authorization: Bearer <token> (the sim was started with SIM_WORLD_TOKEN set)',
          { extensions: { code: 'UNAUTHORIZED', http: { status: 401, headers: { 'www-authenticate': 'Bearer realm="/world"' } } } },
        )
      }
    },
  }
}

/** The landing page (shared with the worker adapter — the same bytes
 *  answer `/` on both transports). */
export function landing(title: string): string {
  return `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title>
<style>body{font-family:system-ui,sans-serif;margin:3rem auto;max-width:44rem;line-height:1.5}
code{background:#f2f2f2;padding:.1em .3em;border-radius:4px}</style></head><body>
<h1>${title}</h1>
<p>A simulated measuring instrument (sim-instruments). Two channels:</p>
<ul>
<li><b><a href="/twin">/twin</a></b> — the SMART digital twin interface (what a certification engine may query). <a href="/twin">GraphiQL</a></li>
<li><b><a href="/world">/world</a></b> — simulated actions (the physical world: loads, environment, time). <a href="/world">GraphiQL</a></li>
</ul>
<p>The twin answers only what a real instrument could legally answer; the world is reality. Try <code>{ groundTruth { appliedLoadKg } }</code> on <code>/world</code>, then <code>mutation { placeLoad(massKg: 40) { groundTruth { appliedLoadKg } } }</code>.</p>
</body></html>`
}

export async function createSimServer(opts: SimServerOptions): Promise<SimServer> {
  const title = opts.title ?? 'simulated instrument'
  const worldYoga = createYoga<{ req: Request }>({
    schema: opts.worldSchema,
    graphqlEndpoint: '/world',
    graphiql: true,
    plugins: opts.worldToken ? [worldMutationGuard(opts.worldToken)] : [],
  })
  const twinYoga = opts.twinSchema
    ? createYoga<{ req: Request }>({ schema: opts.twinSchema, graphqlEndpoint: '/twin', graphiql: true })
    : createYoga<{ req: Request }>({
        schema: createSchema({
          typeDefs: `type Query { _twinPlaceholder: String }`,
          resolvers: {
            Query: {
              _twinPlaceholder: () => {
                throw new GraphQLError(TWIN_PLACEHOLDER_MESSAGE)
              },
            },
          },
        }),
        graphqlEndpoint: '/twin',
        graphiql: true,
        // the placeholder IS the masked message: any resolver error
        // reaches the client as exactly this text, independent of
        // error-class identity across the CJS/ESM boundary.
        maskedErrors: { errorMessage: TWIN_PLACEHOLDER_MESSAGE },
      })

  const server: Server = createServer(async (req, res) => {
    const url = new URL(req.url ?? '/', 'http://localhost')
    // ── CORS (TODO.ops/29): a browser page hosted anywhere (the
    // deployed platform on CloudFront, a docs demo) may drive a LOCAL
    // sim. Preflight + response headers honor the configured origins. ──
    const requestOrigin = typeof req.headers.origin === 'string' ? req.headers.origin : null
    const corsAllow = opts.corsOrigins && requestOrigin
      ? opts.corsOrigins === '*'
        ? '*'
        : corsOriginAllowed(opts.corsOrigins, requestOrigin)
          ? requestOrigin
          : null
      : null
    if (corsAllow) {
      res.setHeader('access-control-allow-origin', corsAllow)
      res.setHeader('vary', 'origin')
    }
    if (req.method === 'OPTIONS') {
      if (corsAllow) {
        res.setHeader('access-control-allow-methods', 'GET, POST, OPTIONS')
        res.setHeader('access-control-allow-headers', 'content-type, authorization')
        res.writeHead(204)
      } else {
        res.writeHead(403, { 'content-type': 'text/plain' })
      }
      return res.end()
    }
    // ── Real-time twin streaming (SSE) ──────────────────────────────
    // GET /twin/stream?targets=indication,state → text/event-stream
    // Emits one event per clock advance, carrying the twin values.
    // Heartbeat every 5s keeps the connection alive through proxies.
    if (url.pathname === '/twin/stream' && req.method === 'GET' && opts.twinStream) {
      return handleTwinStream(req as never, res as never, url, opts.twinStream)
    }
    // ── The OpenAPI twin leg (spec §12 §5.5) ─────────────────────────
    // GET /openapi.json answers the generated document; the REST
    // projection rides /twin/registers/*, /twin/operations/*, and
    // /twin/instrument — the same readers the GraphQL resolvers bind to.
    if (url.pathname === '/openapi.json' && req.method === 'GET' && opts.openApiDoc) {
      res.writeHead(200, { 'content-type': 'application/json' })
      return res.end(JSON.stringify(opts.openApiDoc, null, 2) + '\n')
    }
    if (opts.twinRest && req.method === 'GET' && url.pathname.startsWith('/twin/registers/')) {
      return handleRestRegister(res, url.pathname.slice('/twin/registers/'.length), opts.twinRest)
    }
    if (opts.twinRest && req.method === 'POST' && url.pathname.startsWith('/twin/operations/')) {
      return handleRestOperation(res, url.pathname.slice('/twin/operations/'.length), opts.twinRest)
    }
    if (opts.twinRest && req.method === 'GET' && url.pathname === '/twin/instrument') {
      if (!opts.twinRest.contract.model) {
        res.writeHead(404, { 'content-type': 'text/plain' })
        return res.end('the contract carries no instrument model')
      }
      res.writeHead(200, { 'content-type': 'application/json' })
      return res.end(JSON.stringify(instrumentMirrorObject(opts.twinRest.contract.model, opts.twinRest.contract)) + '\n')
    }
    if (url.pathname === '/world' || url.pathname.startsWith('/world/')) return worldYoga(req, res, { req: req as unknown as Request })
    if (url.pathname === '/twin' || url.pathname.startsWith('/twin/')) return twinYoga(req, res, { req: req as unknown as Request })
    // static bench or the landing page
    if (opts.benchDir) {
      const rel = url.pathname === '/' ? 'index.html' : url.pathname.replace(/^\/+/, '')
      try {
        const body = await readFile(join(opts.benchDir, rel))
        res.writeHead(200, { 'content-type': MIME[extname(rel)] ?? 'application/octet-stream' })
        return res.end(body)
      } catch { /* fall through to landing/404 */ }
    }
    if (url.pathname === '/') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' })
      return res.end(landing(title))
    }
    res.writeHead(404, { 'content-type': 'text/plain' })
    res.end('not found')
  })

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject)
    server.listen(opts.port, () => resolve())
  })
  // the honesty line (TODO.v2/11): say plainly whether /world is guarded
  console.log(opts.worldToken
    ? '/world mutations guarded — Authorization: Bearer <token> required (SIM_WORLD_TOKEN)'
    : '/world channel OPEN — mutations unguarded (localhost dev posture; set SIM_WORLD_TOKEN before any non-local deployment)')
  const addr = server.address()
  const port = typeof addr === 'object' && addr ? addr.port : opts.port
  return {
    url: `http://localhost:${port}`,
    close: () => new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve())),
  }
}

/** Handle a GET /twin/stream request — real-time SSE for continuous
 *  twin indication monitoring.
 *
 *  The stream emits one event per clock advance. Each event carries the
 *  requested twin targets' current values, the servedAt timestamp, and
 *  the freshness status.
 *
 *  Clients connect with:
 *    new EventSource('/twin/stream?targets=indication,state')
 *
 *  Heartbeat comments (`:keepalive\n\n`) every 5s keep the connection
 *  alive through reverse proxies. The `Last-Event-ID` header supports
 *  resumability (future work). */
function handleTwinStream(
  req: NodeJS.ReadableStream & { headers: Record<string, string | undefined> },
  res: NodeJS.WritableStream & { write: (chunk: string) => boolean; writeHead: (status: number, headers: Record<string, string>) => void },
  url: URL,
  source: TwinStreamSource,
): void {
  const requestedTargets = url.searchParams.get('targets')?.split(',').map(s => s.trim()).filter(Boolean)
    ?? source.targets
    ?? ['indication']

  res.writeHead(200, {
    'content-type': 'text/event-stream',
    'cache-control': 'no-cache, no-transform',
    'connection': 'keep-alive',
    'x-accel-buffering': 'no',
  })

  // Emit the current state immediately (the first event a new client sees).
  emitTwinEvent(res, source, requestedTargets)

  // On every clock advance, emit a new event.
  const offClock = source.clock.onAdvance(() => {
    emitTwinEvent(res, source, requestedTargets)
  })

  // Heartbeat every 5 seconds — keeps the connection alive through
  // proxies and load balancers that drop idle connections.
  const heartbeat = setInterval(() => {
    try { res.write(': keepalive\n\n') } catch { /* connection closed */ }
  }, 5000)

  // Clean up on disconnect.
  req.on('close', () => {
    offClock()
    clearInterval(heartbeat)
  })
}

function emitTwinEvent(
  res: NodeJS.WritableStream & { write: (chunk: string) => boolean },
  source: TwinStreamSource,
  targets: string[],
): void {
  const now = source.clock.now()
  const payload = {
    timestamp: now,
    targets: targets.map(target => {
      const value = source.read(target)
      return { target, value }
    }),
  }
  const eventId = String(now)
  const data = JSON.stringify(payload)
  try { res.write(`id: ${eventId}\nevent: twin\ndata: ${data}\n\n`) } catch { /* closed */ }
}


interface RestResponse {
  writeHead: (status: number, headers: Record<string, string>) => void
  end: (body?: string) => void
}

/** GET /twin/registers/<target> — the REST projection of one declared
 *  serve. The read goes through the SAME readerFor the GraphQL
 *  resolver binds to (the signed-serve posture signs here too — the
 *  reader is async under signing). The declared fresh_within bound
 *  rides as the fresh-within-s response header. */
async function handleRestRegister(
  res: RestResponse,
  target: string,
  rest: TwinRestBinding,
): Promise<void> {
  const serve = rest.contract.serves.find(s => s.target === target)
  if (!serve) {
    res.writeHead(404, { 'content-type': 'text/plain' })
    res.end(`no declared serve for register '${target}'`)
    return
  }
  try {
    const value = 'io' in rest ? await readerFor(target, rest.io)() : await rest.read(target)
    const headers: Record<string, string> = { 'content-type': 'application/json' }
    if (serve.freshWithinS != null) headers[FRESH_WITHIN_HEADER] = String(serve.freshWithinS)
    res.writeHead(200, headers)
    res.end(JSON.stringify(value) + '\n')
  } catch (err) {
    res.writeHead(500, { 'content-type': 'text/plain' })
    res.end((err as Error).message)
  }
}

/** POST /twin/operations/<op_id> — the REST projection of one declared
 *  command operation: the instrument-legal implementation runs first,
 *  then the operational state answers (the GraphQL Mutation's shape).
 *  Command operations need a TwinIo; a read-delegate binding (the
 *  composite boot) has no mutation leg to run them through. */
function handleRestOperation(
  res: RestResponse,
  opId: string,
  rest: TwinRestBinding,
): void {
  const op = rest.contract.operations.find(o => o.id === opId && o.kind === 'command')
  if (!op) {
    res.writeHead(404, { 'content-type': 'text/plain' })
    res.end(`no declared command operation '${opId}'`)
    return
  }
  if (!('io' in rest)) {
    res.writeHead(501, { 'content-type': 'text/plain' })
    res.end(`command operation '${opId}' is declared but this twin binding runs no operations (the composite twin exposes no mutation leg)`)
    return
  }
  try {
    rest.io.operations?.[op.id]?.()
    res.writeHead(200, { 'content-type': 'application/json' })
    res.end(JSON.stringify({ state: rest.io.instrument.operationalState() }) + '\n')
  } catch (err) {
    res.writeHead(500, { 'content-type': 'text/plain' })
    res.end((err as Error).message)
  }
}
